import type { LocalizedString } from "@/i18n/types";

export type Ingredient = {
  amount: LocalizedString;
  name: LocalizedString;
};

export type Recipe = {
  slug: string;
  title: LocalizedString;
  description: LocalizedString;
  categories: string[];
  servings: number;
  prepMinutes: number;
  cookMinutes: number;
  level: LocalizedString;
  image: string;
  youtubeUrl?: string;
  ingredients: Ingredient[];
  steps: LocalizedString[];
};

const L = (ko: string, en: string): LocalizedString => ({ ko, en });
const easy = L("쉬움", "Easy");
const medium = L("보통", "Medium");

function ing(
  amountKo: string,
  amountEn: string,
  nameKo: string,
  nameEn: string,
): Ingredient {
  return {
    amount: L(amountKo, amountEn),
    name: L(nameKo, nameEn),
  };
}

